 {DrawingWindow reopened;clientOk(reopened.openPath(first));require(reopened.editor()->sheet().style.extensionGap==1&&reopened.editor()->sheet().style.dimensionOffset==10,"distanze conservate nel file collegato");require(reopened.findChild<QToolBar *>("drawingCustomBar")->actions().size()==1,"personalizzazione persistente dopo riapertura");}
